<script lang="ts">
  import Icon from './Icon.svelte';
  import type { Keymap } from './keymap';
  import type { ButtonId } from './actions';
  let { speed, pitch, keymap, controls, runButton }:
    { speed:number; pitch:number; keymap:Keymap; controls:(speed:number,pitch:number)=>void; runButton:(id:ButtonId,payload?:{speed?:number})=>void } = $props();
</script>
        <div class="practice-controls">
